<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Cats FAQ</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --panel: rgba(255, 255, 255, 0.9);
      --panel-border: #dbe3f0;
      --text: #162033;
      --muted: #5e6b84;
      --accent: #4f7cff;
      --accent-soft: #eaf0ff;
      --shadow: 0 20px 60px rgba(23, 36, 72, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #ffffff 0, #f3f7ff 38%, var(--bg) 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      width: min(960px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 5rem 0 4rem;
    }

    .hero {
      margin-bottom: 2rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 1rem 0 0.75rem;
      font-size: clamp(2.4rem, 4vw, 4.4rem);
      line-height: 1.02;
      letter-spacing: -0.04em;
    }

    .lede {
      max-width: 60ch;
      margin: 0;
      font-size: 1.08rem;
      line-height: 1.7;
      color: var(--muted);
    }

    .faq {
      display: grid;
      gap: 1rem;
      margin-top: 2rem;
    }

    .example {
      border: 1px solid var(--panel-border);
      border-radius: var(--radius);
      background: var(--panel);
      box-shadow: var(--shadow);
      overflow: clip;
      backdrop-filter: blur(14px);
    }

    .question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.25rem 1.4rem;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
      text-align: left;
      cursor: pointer;
    }

    .question:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: -3px;
    }

    .question span {
      font-size: 1.05rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .chevron {
      flex: none;
      width: 2rem;
      height: 2rem;
      border-radius: 999px;
      display: grid;
      place-items: center;
      background: var(--accent-soft);
      color: var(--accent);
      transition: transform 0.2s ease;
    }

    .question[aria-expanded="true"] .chevron {
      transform: rotate(180deg);
    }

    .details {
      display: grid;
      gap: 0.85rem;
      padding: 0 1.4rem 1.35rem;
      color: var(--muted);
      line-height: 1.75;
    }

    .details[hidden] {
      display: none;
    }

    .details p {
      margin: 0;
    }

    .details ul {
      margin: 0;
      padding-left: 1.25rem;
    }

    .details li + li {
      margin-top: 0.4rem;
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 1rem, 960px);
        padding-top: 4.25rem;
      }

      .question {
        padding: 1.1rem 1.1rem;
      }

      .details {
        padding: 0 1.1rem 1.1rem;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <header class="hero">
      <span class="eyebrow">Cat care guide</span>
      <h1>Cats FAQ</h1>
      <p class="lede">
        Quick answers to common questions about cat behavior, care, and what makes them such
        charming little chaos machines.
      </p>
    </header>

    <section class="faq" aria-label="Frequently asked questions about cats">
      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
          <span>Why do cats purr?</span>
          <span class="chevron" aria-hidden="true">⌄</span>
        </button>
        <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
          <p>
            Cats purr for comfort, communication, and sometimes self-soothing. You will often hear
            it when they are relaxed, but cats may also purr when they are nervous or in pain.
          </p>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
          <span>How much sleep do cats need?</span>
          <span class="chevron" aria-hidden="true">⌄</span>
        </button>
        <div class="details" id="answer-2" role="region" aria-labelledby="question-2" hidden>
          <p>
            Most adult cats sleep around 12 to 16 hours a day. Kittens and senior cats can sleep
            even more, which helps them save energy for bursts of play and hunting behavior.
          </p>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
          <span>Why do cats knead blankets?</span>
          <span class="chevron" aria-hidden="true">⌄</span>
        </button>
        <div class="details" id="answer-3" role="region" aria-labelledby="question-3" hidden>
          <p>
            Kneading is a comforting, instinctive behavior that starts in kittenhood. Cats may
            knead when they feel safe, content, or ready to settle in for a nap.
          </p>
        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
          <span>What is the best way to keep a cat entertained?</span>
          <span class="chevron" aria-hidden="true">⌄</span>
        </button>
        <div class="details" id="answer-4" role="region" aria-labelledby="question-4" hidden>
          <p>
            Rotate toys, offer scratching posts, and schedule short play sessions with wand toys or
            puzzle feeders. Variety keeps cats mentally sharp and physically active.
          </p>
        </div>
      </div>
    </section>
  </main>

  <script>
    const items = document.querySelectorAll('.example');

    items.forEach((item) => {
      const button = item.querySelector('.question');
      const panel = item.querySelector('.details');

      button.addEventListener('click', () => {
        const expanded = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', String(!expanded));
        panel.hidden = expanded;
      });
    });
  </script>
</body>
</html>
